177	/// Two-pass `[[package]]` rule lookup with Prefixed-over-Bare specificity.
178	///
179	/// Pass 1: iterate `cfg.packages` in Vec (TOML declaration) order. Return a reference
180	/// to the `PackageConfig` of the first entry `(rule_id, pkg_cfg)` where
181	/// `rule_id.ecosystem().is_some()` AND `rule_id.matches(id)`. Prefixed rules
182	/// (those with an explicit ecosystem prefix such as `cargo/`, `npm/`, `pypi/`)
183	/// always beat Bare rules regardless of declaration order in `callisto.toml`.
184	///
185	/// Pass 2 (only if Pass 1 found nothing): iterate `cfg.packages` in Vec order.
186	/// Return the first entry where `rule_id.matches(id)` (no ecosystem restriction).
187	///
188	/// Returns `None` if neither pass finds a match.
189	///
190	/// The function MUST NOT sort, partition-then-sort, or otherwise reorder `cfg.packages`.
191	/// Two-pass specificity is achieved solely by two separate linear scans over the
192	/// unmodified slice.
193	pub(crate) fn resolve_package_config<'a>(
194	    id: &PackageId,
195	    cfg: &'a ResolvedConfig,
196	) -> Option<&'a PackageConfig> {
197	    cfg.packages
198	        .iter()
199	        .find(|(rule_id, _)| rule_id.ecosystem().is_some() && rule_id.matches(id))
200	        .or_else(|| cfg.packages.iter().find(|(rule_id, _)| rule_id.matches(id)))
201	        .map(|(_, pcfg)| pcfg)
202	}
