221	pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
222	    let callisto_toml = root.join("callisto.toml");
223	    let raw = if callisto_toml.exists() {
224	        let content = fs::read_to_string(&callisto_toml).map_err(|e| ConfigError::Read {
225	            path: callisto_toml.clone(),
226	            message: e.to_string(),
227	        })?;
228	        toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
229	            path: callisto_toml.clone(),
230	            message: e.to_string(),
231	        })?
232	    } else {
233	        RawConfig::default()
234	    };
235	
236	    let mut provenance = BTreeMap::new();
237	
238	    let changesets_dir_str = raw
239	        .changesets
