861	    /// Both rules set release_trigger with different values so the winner is directly observable.
862	    /// npm/foo (first): release-trigger = "auto" -> release_trigger = Some(Auto).
863	    /// cargo/foo (second): release-trigger = "changeset" -> release_trigger = Some(Changeset).
864	    /// Pass 1 returns the first matching Prefixed entry in Vec (TOML declaration) order.
865	    /// Vec order must govern: npm/foo is first -> release_trigger must be Some(Auto).
866	    /// A sorted implementation (cargo < npm alphabetically) would return Some(Changeset).
867	    #[test]
868	    fn resolve_package_config_vec_declaration_order_not_alphabetical_sort() {
869	        let tmp = tempfile::tempdir().expect("tempdir");
870	        let root = tmp.path();
871	        // npm/foo FIRST in Vec: release-trigger = "auto"
872	        // cargo/foo SECOND in Vec: release-trigger = "changeset"
873	        // Querying Bare("foo"): pass 1 returns npm/foo (first Prefixed match) -> Some(Auto).
874	        // A sorted implementation would return cargo/foo (cargo < npm) -> Some(Changeset).
875	        fs::write(
876	            root.join("callisto.toml"),
877	            "[[package]]\nmatch = \"npm/foo\"\nrelease-trigger = \"auto\"\n\n[[package]]\nmatch = \"cargo/foo\"\nrelease-trigger = \"changeset\"\n",
878	        )
879	        .expect("write callisto.toml");
880	        let cfg = load(root).expect("load should succeed");
881	        let id = PackageId::parse("foo").unwrap();
882	        let result = resolve_package_config(&id, &cfg);
883	        let pcfg = result.expect("resolve_package_config must return Some for Bare(\"foo\")");
884	        assert_eq!(
885	            pcfg.release_trigger,
886	            Some(ReleaseTrigger::Auto),
887	            "npm/foo (declared first) must win over cargo/foo (declared second) — Vec order, \
888	             not alphabetical sort, governs first-match-wins (AC-F5). \
889	             Some(Changeset) means cargo/foo won due to alphabetical sort. Got: {:?}",
890	            pcfg.release_trigger
891	        );
892	    }
893	}
